def _family(schema: str) -> str:
    """The table's digit for a schema name such as ``IFC4X3_ADD2``."""
    name = schema.upper()
    return "2" if name.startswith("IFC2X3") else "3" if name.startswith("IFC4X3") else "4"


def inverses(schema: str) -> list[tuple[str, str, str, str]]:
    """``(declaring class, inverse name, referring class, attribute)`` for every inverse attribute of ``schema``."""
    family = _family(schema)
    found = []
    for line in _TABLE.strip().splitlines():
        if line:
            declaring, name, referring, attribute, schemas = line.split(" ")
            if family in schemas:
                found.append((declaring, name, referring, attribute))
    return found
